import{_ as r,C as d,o,c as i,a5 as e,E as s}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"器件与工艺入门","description":"从 PN 结和 MOSFET 出发，认识 CMOS、先进器件结构、微纳加工与良率。","frontmatter":{"title":"器件与工艺入门","description":"从 PN 结和 MOSFET 出发，认识 CMOS、先进器件结构、微纳加工与良率。"},"headers":[],"relativePath":"explore-ic/devices-process.md","filePath":"explore-ic/devices-process.md","lastUpdated":1795531638000}'),l={name:"explore-ic/devices-process.md"};function h(n,t,c,p,E,u){const a=d("CourseTable");return o(),i("div",null,[t[0]||(t[0]=e('<h1 id="器件与工艺入门" tabindex="-1">器件与工艺入门 <a class="header-anchor" href="#器件与工艺入门" aria-label="Permalink to &quot;器件与工艺入门&quot;">​</a></h1><p>画在电路图里的晶体管，最终要靠材料、几何结构与加工工艺实现。器件与工艺学习的主线是：<strong>电荷如何运动，电场如何控制运动，制造怎样把结构做出来</strong>。不必一开始就推导全部公式，但应能把结构、曲线与电路行为联系起来。</p><h2 id="pn-结-电荷形成的内部边界" tabindex="-1">PN 结：电荷形成的内部边界 <a class="header-anchor" href="#pn-结-电荷形成的内部边界" aria-label="Permalink to &quot;PN 结：电荷形成的内部边界&quot;">​</a></h2><p>通过掺杂，可以使半导体以电子或空穴作为主要载流子，分别形成 N 型和 P 型区域。两者接触后，载流子扩散与内建电场达到平衡，形成耗尽区。施加外部偏置会改变势垒，因此正向与反向电流行为不同。</p><p>PN 结不只是“只许一个方向导电”的理想二极管。它具有结电容、漏电和击穿等非理想行为，也是理解光电探测器、太阳能电池与许多晶体管结构的起点。看曲线时要注意温度、面积、偏置和坐标是否取对数。</p><h2 id="mosfet-用栅极电场控制沟道" tabindex="-1">MOSFET：用栅极电场控制沟道 <a class="header-anchor" href="#mosfet-用栅极电场控制沟道" aria-label="Permalink to &quot;MOSFET：用栅极电场控制沟道&quot;">​</a></h2><p>金属氧化物半导体场效应晶体管（Metal-Oxide-Semiconductor Field-Effect Transistor，MOSFET）利用栅极对沟道的静电控制，调节源漏之间的电流。栅极通过介质与沟道隔开，但实际仍存在电容和漏电，不是完全没有代价的控制端。</p><p>入门先理解三件事：阈值电压决定开启的尺度；栅压与漏压共同决定工作状态；器件尺寸影响驱动能力、电容和失配。长沟道平方律有助于建立直觉，但不是先进节点的精确模型；工程仿真应使用与工艺匹配的模型。</p><h2 id="cmos-互补器件组成逻辑" tabindex="-1">CMOS：互补器件组成逻辑 <a class="header-anchor" href="#cmos-互补器件组成逻辑" aria-label="Permalink to &quot;CMOS：互补器件组成逻辑&quot;">​</a></h2><p>互补金属氧化物半导体（Complementary MOS，CMOS）使用 NMOS 与 PMOS。以反相器为例，输入变化会使上拉与下拉网络交替工作。理想静态状态下不应存在持续贯通电流，但实际电路仍有漏电，切换时还需要给电容充放电。</p><p>常见动态功耗近似与活动率、电容、供电电压平方和频率成正比。这解释了为什么降低电压很有吸引力，也解释了为什么时钟、电源、互连与体系结构都和器件有关。数字电路的“0”和“1”背后仍是连续变化的电压。</p><h2 id="缩小尺寸为什么越来越难" tabindex="-1">缩小尺寸为什么越来越难 <a class="header-anchor" href="#缩小尺寸为什么越来越难" aria-label="Permalink to &quot;缩小尺寸为什么越来越难&quot;">​</a></h2><p>短沟道效应（Short-Channel Effects）是沟道缩短后，漏极等因素更强地影响沟道势垒的一组现象，包括阈值变化、漏致势垒降低等。再加上速度饱和、隧穿漏电和工艺变异，不能简单把长沟道器件按比例缩小。</p><table tabindex="0"><thead><tr><th>结构</th><th>核心想法</th><th>不应误解为</th></tr></thead><tbody><tr><td>平面 MOSFET</td><td>栅极从沟道一侧控制导电</td><td>所有现代产品都已不用</td></tr><tr><td>鳍式晶体管（FinFET）</td><td>用立体鳍形沟道增强栅控</td><td>只把平面器件画得更高</td></tr><tr><td>环栅晶体管（Gate-All-Around，GAA）</td><td>栅极环绕纳米线或纳米片沟道</td><td>工艺与寄生问题已经消失</td></tr><tr><td>互补场效应晶体管（Complementary FET，CFET）</td><td>探索将互补器件垂直堆叠，节省平面占用</td><td>所有厂商均已大规模量产</td></tr></tbody></table><p>器件结构的演进需要和接触、互连、散热以及设计规则一起考虑。研究演示、风险试产与稳定量产是不同阶段，不能只凭结构名称判断产品成熟度。</p><h2 id="工艺节点不等于某个统一尺寸" tabindex="-1">工艺节点不等于某个统一尺寸 <a class="header-anchor" href="#工艺节点不等于某个统一尺寸" aria-label="Permalink to &quot;工艺节点不等于某个统一尺寸&quot;">​</a></h2><p>“几纳米节点”今天更多是某代工艺的平台名称，不能直接当成晶体管栅长，也不能拿不同厂商的名称作严格等比例比较。要比较工艺，应看实际单元密度、速度、功耗、互连、可用 IP、成本与可靠性，且明确设计条件。</p><p>模拟、射频、功率与传感器产品可能更需要高电压、低噪声、厚金属、特殊材料或成熟模型。成熟节点并不等于落后应用，先进逻辑节点也不是所有芯片的最优解。</p><h2 id="一层一层制造出来" tabindex="-1">一层一层制造出来 <a class="header-anchor" href="#一层一层制造出来" aria-label="Permalink to &quot;一层一层制造出来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>基本工序</th><th>做什么</th><th>为什么影响电路</th></tr></thead><tbody><tr><td>光刻（Lithography）</td><td>把掩模图形转移到光刻胶等材料上</td><td>对准、分辨率与图形误差影响几何形状</td></tr><tr><td>刻蚀（Etching）</td><td>有选择地去除材料</td><td>选择比、侧壁形状与损伤影响器件性能</td></tr><tr><td>沉积（Deposition）</td><td>形成导体、半导体或介质薄膜</td><td>厚度、成分、覆盖性和缺陷影响一致性</td></tr><tr><td>掺杂（Doping）</td><td>通过注入或扩散等方式改变载流子分布</td><td>决定结、阈值和接触特性</td></tr><tr><td>退火与平坦化</td><td>调整材料状态，恢复或整平表面</td><td>影响热预算、应力和后续加工</td></tr></tbody></table><p>真正的制造流程反复组合这些工序，还需要清洗、量测和过程控制。前道主要形成器件，后道主要形成互连；不要与设计流程中的“数字前端/后端”混淆。</p><h2 id="良率-不是每颗裸片都合格" tabindex="-1">良率：不是每颗裸片都合格 <a class="header-anchor" href="#良率-不是每颗裸片都合格" aria-label="Permalink to &quot;良率：不是每颗裸片都合格&quot;">​</a></h2><p>良率（Yield）是按指定判定条件计算的合格比例。颗粒缺陷、工艺波动、参数超限和互连问题，都可能导致不合格；晶圆测试、封装后测试和最终产品筛选的良率也不是同一个分母。</p><p>相同缺陷密度下，更大的裸片通常更容易遇到随机缺陷，但实际良率还受设计、冗余、测试条件和工艺成熟度影响。讨论成本时，不能只算晶圆面积，还要考虑可用裸片、封装与测试。</p><h2 id="在上科大对应哪些课" tabindex="-1">在上科大对应哪些课 <a class="header-anchor" href="#在上科大对应哪些课" aria-label="Permalink to &quot;在上科大对应哪些课&quot;">​</a></h2>',25)),s(a,{codes:"EE120,EE220,EE224A,EE2211"}),t[1]||(t[1]=e('<ul><li><strong>EE120 半导体器件基础</strong>：适合作为器件方向入口。官方先修写的是普通物理 II <strong>或</strong> EE130，不是要求二者同时完成。</li><li><strong>EE220 半导体器件物理</strong>：向更深入的器件物理推进；先修列的是半导体材料与器件、半导体物理原理、固体物理或同等课程，不能把 EE120 自动视作唯一且充分的先修证明。</li><li><strong>EE224A 微纳器件工艺基础</strong>：从制造视角补齐知识，官方先修为普通物理 I、化学 I。</li><li><strong>EE2211 微电子器件</strong>：另一门器件进阶课程，官方先修为 EE111 与物理。</li></ul><p>后面三门在年度表中列为研究生课程。本科生能否选修、需要哪些准备，以当学期规定与任课教师确认为准。继续看 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/">器件、工艺与光电路线</a>，或从 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/devices">器件科研</a> 找问题入口。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年官方开课表</a>：上述课程代码、名称与先修条件。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">学院本硕博课程体系</a>。</li><li><a href="https://irds.ieee.org/" target="_blank" rel="noreferrer">IEEE 国际器件与系统路线图</a>：器件、工艺与系统技术趋势参考；路线图不等于已完成量产。</li></ul>',4))])}const f=r(l,[["render",h]]);export{b as __pageData,f as default};
